from sales_dashboard.loader import dedupe_sessions, daily_conversion_counts, parse_session_log
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def session(id_, day, converted):
    return {"id": id_, "day": day, "converted": converted}


def test_conversion_rate_none_counts_in_denominator():
    assert conversion_rate([session("a", 1, True), session("b", 1, None),
                            session("c", 1, False)]) == 1 / 3
    assert conversion_rate([]) == 0.0
    assert conversion_rate([session("a", 1, None)]) == 0.0


def test_pooled_rate_weights_sessions_not_groups():
    groups = {"small": [session("a", 1, True)],
              "large": [session(str(i), 1, False) for i in range(3)], "empty": []}
    assert pooled_conversion_rate(groups) == 0.25
    assert pooled_conversion_rate({}) == 0.0
    assert pooled_conversion_rate({"empty": []}) == 0.0


@pytest.mark.parametrize("days,expected", [(0, 0), (1, 3), (2, 5), (3, 6), (8, 6)])
def test_conversions_in_window(days, expected):
    assert conversions_in_window([1, 2, 3], days) == expected
    assert conversions_in_window([], days) == 0


def test_parse_fields_skips_blank_and_comments():
    lines = ["  # comment,even,with,commas", "", " \t ", " x , 3 , 1 ",
             "y, -2, 0", " z , 4 ,  "]
    assert parse_session_log(lines) == [session("x", 3, True), session("y", -2, False),
                                        session("z", 4, None)]


@pytest.mark.parametrize("line", ["missing,fields", "too,many,fields,here", "id,nope,1", "id,1,unknown"])
def test_parse_errors_report_input_line_including_skipped_lines(line):
    with pytest.raises(ValueError, match=r"line 3\b"):
        parse_session_log(["# comment", " ", line])


def test_dedupe_keeps_last_duplicate_and_sorts_by_day_then_id():
    events = [session("a", 1, True), session("c", 3, True), session("b", 2, False),
              session("a", 2, None), session("c", 1, False)]
    assert dedupe_sessions(events) == [events[4], events[3], events[2]]
    assert dedupe_sessions([]) == []


def test_daily_counts_range_gaps_and_unconverted():
    events = [session("a", 0, True), session("b", 1, True), session("c", 1, True),
              session("d", 2, None), session("e", 3, False), session("f", 4, True)]
    assert daily_conversion_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_conversion_counts([], 2, 3) == [0, 0]
    assert daily_conversion_counts(events, 4, 3) == []


def test_campaign_summary_uses_calendar_days_weighted_rate_and_nonempty_groups():
    groups = {"a": [session("a", 1, True)],
              "b": [session("b", 3, True), session("c", 5, False)], "empty": []}
    assert campaign_summary(groups, 2) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert campaign_summary(groups, 3) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert campaign_summary(groups, 0)["recent"] == 0
    assert campaign_summary({"empty": []}, 5) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert campaign_summary({}, 5) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {"z": [session("z", 1, True)], "empty": [],
              "a": [session("a", 1, True)], "b": [session("b", 1, False)]}
    assert top_converting_groups(groups, 9) == ["a", "z", "b"]
    assert top_converting_groups(groups, 1) == ["a"]
    assert top_converting_groups(groups, 0) == []


def test_group_rates_include_empty_in_sorted_order():
    groups = {"z": [], "b": [session("b", 1, None)], "a": [session("a", 1, True)]}
    result = conversion_rate_by_group(groups)
    assert result == {"a": 1.0, "b": 0.0, "z": None}
    assert list(result) == ["a", "b", "z"]


def test_longest_streak_resets_on_zero_and_negative():
    assert longest_conversion_streak([1, 2, 0, 3, 4, 5, -1, 6]) == 3
    assert longest_conversion_streak([0, -2, 0]) == 0
    assert longest_conversion_streak([]) == 0
